import QRCode from "qrcode";

const OPTS = { errorCorrectionLevel: "M" as const, margin: 1, color: { dark: "#141512", light: "#ffffff" } };

/** SVG markup generated by the qrcode library from our own URL (safe to inline). */
export function qrSvg(url: string): Promise<string> {
  return QRCode.toString(url, { ...OPTS, type: "svg" });
}

export function qrPng(url: string, width = 1024): Promise<Buffer> {
  return QRCode.toBuffer(url, { ...OPTS, type: "png", width });
}
